325→// MermaidDiagram generates a Mermaid state diagram from the transition table.
326→// The diagram is derived by calling Transition() for representative context
327→// variants per phase/event, so it stays in sync with the implementation.
328→func MermaidDiagram() string {
329→	var b strings.Builder
330→	b.WriteString("stateDiagram-v2\n")
331→
332→	// State declarations with descriptions.
333→	b.WriteString("    state \"IDLE\" as idle\n")
334→	b.WriteString("    state \"ACTIVE\" as active\n")
335→	b.WriteString("    state \"ENDED\" as ended\n")
336→	b.WriteString("\n")
337→
338→	// Context variants for GitCommit: rebase, files/no-files.
339→	type contextVariant struct {
340→		label string
341→		ctx   TransitionContext
342→	}
343→
344→	// For each phase/event, generate edges.
345→	for _, phase := range allPhases {
346→		for _, event := range allEvents {
347→			var variants []contextVariant
348→			switch {
349→			case event == EventGitCommit && phase == PhaseEnded:
350→				// HasFilesTouched only affects PhaseEnded transitions;
351→				// other phases produce identical edges for both values.
352→				variants = []contextVariant{
353→					{"[files]", TransitionContext{HasFilesTouched: true}},
354→					{"[no files]", TransitionContext{HasFilesTouched: false}},
355→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
356→				}
357→			case event == EventGitCommit:
358→				variants = []contextVariant{
359→					{"", TransitionContext{}},
360→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
361→				}
362→			default:
363→				variants = []contextVariant{
364→					{"", TransitionContext{}},
365→				}
366→			}
367→
368→			for _, v := range variants {
369→				result := Transition(phase, event, v.ctx)
370→
371→				// Build edge label.
372→				label := event.String()
373→				if v.label != "" {
374→					label += " " + v.label
375→				}
376→				if len(result.Actions) > 0 {
377→					actionNames := make([]string, 0, len(result.Actions))
378→					for _, a := range result.Actions {
379→						actionNames = append(actionNames, a.String())
380→					}
381→					label += " / " + strings.Join(actionNames, ", ")
382→				}
383→
384→				from := string(phase)
385→				to := string(result.NewPhase)
386→
387→				fmt.Fprintf(&b, "    %s --> %s : %s\n", from, to, label)
388→			}
389→		}
390→	}
391→
392→	return b.String()
393→}
